class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

def index_pairs(text, words):
    root = TrieNode()
    for w in words:                                       # build the trie ONCE
        node = root
        for c in w:
            node = node.children.setdefault(c, TrieNode())
        node.is_end = True

    result = []
    n = len(text)
    for i in range(n):
        node = root
        for j in range(i, n):
            c = text[j]
            if c not in node.children:
                break                                        # no further match possible
            node = node.children[c]
            if node.is_end:
                result.append([i, j])                          # record every match found
    return result

