import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEnd = false;
}

public class Main {
    static List<int[]> indexPairs(String text, String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {                                  // build the trie ONCE
            TrieNode node = root;
            for (char c : w.toCharArray()) node = node.children.computeIfAbsent(c, k -> new TrieNode());
            node.isEnd = true;
        }
        List<int[]> result = new ArrayList<>();
        int n = text.length();
        for (int i = 0; i < n; i++) {
            TrieNode node = root;
            for (int j = i; j < n; j++) {
                char c = text.charAt(j);
                if (!node.children.containsKey(c)) break;             // no further match possible
                node = node.children.get(c);
                if (node.isEnd) result.add(new int[]{i, j});             // record every match found
            }
        }
        return result;
    }
}

