#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; bool isEnd = false; };

vector<vector<int>> indexPairs(string text, vector<string>& words) {
    TrieNode* root = new TrieNode();
    for (auto& w : words) {                                       // build the trie ONCE
        TrieNode* node = root;
        for (char c : w) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();
            node = node->children[c];
        }
        node->isEnd = true;
    }
    vector<vector<int>> result;
    int n = text.size();
    for (int i = 0; i < n; i++) {
        TrieNode* node = root;
        for (int j = i; j < n; j++) {
            char c = text[j];
            if (!node->children.count(c)) break;                        // no further match possible
            node = node->children[c];
            if (node->isEnd) result.push_back({i, j});                     // record every match found
        }
    }
    return result;
}
